{"command": "create", "path": "/root/recalc.py", "file_text": """"Recalculate formulas in an xlsx file using LibreOffice headless, scan for errors."""
import json
import os
import shutil
import subprocess
import sys
import tempfile
from openpyxl import load_workbook

ERRORS = {"#REF!", "#DIV/0!", "#VALUE!", "#N/A", "#NAME?", "#NUM!", "#NULL!"}


def recalc(path, timeout=120):
    path = os.path.abspath(path)
    outdir = tempfile.mkdtemp()
    cmd = [
        "libreoffice", "--headless", "--calc",
        "--convert-to", "xlsx",
        "--outdir", outdir,
        path,
    ]
    # Also need to force recalc on load; libreoffice does this when converting
    env = os.environ.copy()
    env.setdefault("HOME", "/tmp")
    subprocess.run(cmd, check=True, timeout=timeout, env=env,
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    base = os.path.basename(path)
    produced = os.path.join(outdir, base)
    shutil.move(produced, path)
    shutil.rmtree(outdir, ignore_errors=True)

    wb = load_workbook(path, data_only=True)
    errors = {}
    total_formulas = 0
    # Count formulas (reload with data_only=False)
    wb_f = load_workbook(path, data_only=False)
    for ws in wb_f.worksheets:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value, str) and c.value.startswith("="):
                    total_formulas += 1
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for c in row:
                v = c.value
                if isinstance(v, str) and v in ERRORS:
                    errors.setdefault(v, {"count": 0, "locations": []})
                    errors[v]["count"] += 1
                    if len(errors[v]["locations"]) < 20:
                        errors[v]["locations"].append(f"{ws.title}!{c.coordinate}")
    result = {
        "status": "errors_found" if errors else "success",
        "total_errors": sum(e["count"] for e in errors.values()),
        "total_formulas": total_formulas,
    }
    if errors:
        result["error_summary"] = errors
    return result


if __name__ == "__main__":
    p = sys.argv[1]
    t = int(sys.argv[2]) if len(sys.argv) > 2 else 120
    print(json.dumps(recalc(p, t), indent=2))
