from openpyxl import load_workbook
wb = load_workbook('pwt110.xlsx', read_only=True)
ws = wb['Legend']
# find rgdpna meaning
for row in ws.iter_rows(min_row=1, max_row=100, values_only=True):
    for v in row:
        if v and 'rgdpna' in str(v).lower():
            print(row); break

ws = wb['Data']
headers = next(ws.iter_rows(min_row=1, max_row=1, values_only=True))
idx_rgdpna = headers.index('rgdpna')
print('rgdpna idx:', idx_rgdpna)
rows = []
for row in ws.iter_rows(min_row=2, values_only=True):
    if row[1] == 'Georgia' and row[3] in range(1990, 2024):
        rows.append((row[3], row[idx_rgdpna]))
for y, v in rows:
    print(y, v)
EOF", "summary": "Get PWT rgdpna for Georgia"}

